  { id: 'tomato-soup', name: 'Tomato soup', category: 'Canned goods', quantity: 4, restocked: '2026-10-02' },
  { id: 'brown-rice', name: 'Brown rice, 1 kg', category: 'Dry goods', quantity: 18, restocked: '2026-10-11' },
  { id: 'rolled-oats', name: 'Rolled oats', category: 'Dry goods', quantity: 9, restocked: '2026-10-07' },
  { id: 'apples', name: 'Apples', category: 'Produce', quantity: 32, restocked: '2026-10-15' },
  { id: 'carrots', name: 'Carrots', category: 'Produce', quantity: 0, restocked: '2026-09-28' },
  { id: 'toothpaste', name: 'Toothpaste', category: 'Toiletries', quantity: 12, restocked: '2026-10-09' },
  { id: 'bar-soap', name: 'Bar soap', category: 'Toiletries', quantity: 3, restocked: '2026-09-30' },
];

const dateFormat = new Intl.DateTimeFormat('en-GB', { dateStyle: 'long', timeZone: 'UTC' });

/** Formats an ISO day the same way on the server and in every browser time zone. */
export function formatDay(day: string) {
  return dateFormat.format(new Date(`${day}T00:00:00Z`));
}

/** Today in the volunteer's own time zone, as an ISO `YYYY-MM-DD` date. */
export function today() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}
